import json
import re

def parse_json_objects(text):
    """Parse multiple JSON objects concatenated together."""
    objects = []
    # Remove the INFO log line at the start if present
    # Find all top-level JSON objects
    brace_depth = 0
    current = []
    started = False
    for char in text:
        if char == '{':
            brace_depth += 1
            started = True
        if started:
            current.append(char)
        if char == '}':
            brace_depth -= 1
            if brace_depth == 0 and started:
                objects.append(json.loads(''.join(current)))
                current = []
                started = False
    return objects

# Parse orders
with open('/tmp/orders_raw.txt', 'r') as f:
    orders_text = f.read()
orders = parse_json_objects(orders_text)
print(f"Found {len(orders)} orders")

# Aggregate sales by (product_id, variation_id)
sales = {}
for order in orders:
    for item in order.get('line_items', []):
        pid = item['product_id']
        vid = item['variation_id']
        qty = item['quantity']
        key = (pid, vid)
        sales[key] = sales.get(key, 0) + qty

print(f"\nSales by (product_id, variation_id):")
for (pid, vid), qty in sorted(sales.items()):
    print(f"  product={pid}, variation={vid}: {qty}")

# Find best-selling variation per product
best_sales = {}
for (pid, vid), qty in sales.items():
    if pid not in best_sales or qty > best_sales[pid][1]:
        best_sales[pid] = (vid, qty)

print(f"\nBest-selling variation per product:")
for pid, (vid, qty) in sorted(best_sales.items()):
    print(f"  product={pid}, best_variation={vid}, qty_sold={qty}")

# Parse products to get variations and their images
# The products output starts with an INFO line, then has products
# Products are returned as an array
with open('/tmp/products_raw.txt', 'r') as f:
    products_text = f.read()

# Try to parse as array first
try:
    # Strip the INFO line
    start_idx = products_text.find('[')
    if start_idx >= 0:
        products_text_arr = products_text[start_idx:]
        products = json.loads(products_text_arr)
    else:
        products = parse_json_objects(products_text)
except:
    products = parse_json_objects(products_text)

print(f"\nFound {len(products)} products")

# Build mapping: product_id -> best_variation_image_id
updates = []
for product in products:
    pid = product['id']
    if pid in best_sales:
        best_vid = best_sales[pid][0]
        # Find the variation in this product's variations list
        for var in product.get('variations', []):
            if var['id'] == best_vid:
                img_id = var.get('image', {}).get('id')
                if img_id:
                    current_img = product.get('images', [{}])[0].get('id') if product.get('images') else None
                    print(f"  Product {pid} ({product['name']}): best_var={best_vid}, var_img={img_id}, current_main={current_img}")
                    if img_id != current_img:
                        updates.append({
                            'id': pid,
                            'images': [{'id': img_id}]
                        })
                    break

print(f"\nNeed to update {len(updates)} products")
for u in updates:
    print(f"  Update product {u['id']}: set image id to {u['images'][0]['id']}")

